/* eslint-disable no-undef */
//
// notify-sw.js — the notification half of the service worker.
//
// ⚠⚠ Why a separate file. The worker itself is GENERATED by workbox
// (vite.config.ts → VitePWA), so there is nowhere in it to write a handler;
// `workbox.importScripts` pulls this one in instead. Keep it free of build
// steps and of anything newer than the browsers filex supports: it is served
// verbatim from `web/public/`, never compiled.
//
// It answers two things a page cannot:
//
//   • NOTIFICATIONCLICK — a toast raised by the worker (the only kind Android
//     Chrome allows, where `new Notification(...)` throws) has no page to call
//     back into. Its click has to be handled here, and it has to REUSE an open
//     tab rather than piling up new ones: someone who leaves the app open all
//     day and taps four notifications should end up with one window on the
//     fourth file, not four windows.
//
//   • PUSH — a payload that arrives while no tab is open at all. filex has no
//     push subscription today (no VAPID key, nothing calls `subscribe()`), so
//     nothing reaches this handler yet; it is here so that the day something
//     does, the toast it raises is the SAME branded toast the in-page channel
//     raises, instead of the browser's "This site has been updated in the
//     background" placeholder — which is what a push handler's ABSENCE
//     produces, not silence.
//
// ⚠ Both paths take their icon and badge from PNGs. Chromium's notification
// decoder has no SVG, so `icon.svg` there is not a small logo, it is none.

const FILEX_ICON = '/admin/icons/icon-192.png';
const FILEX_BADGE = '/admin/icons/badge-96.png';

self.addEventListener('notificationclick', (event) => {
  const notification = event.notification;
  notification.close();

  const data = notification.data || {};
  const target = typeof data.url === 'string' && data.url ? data.url : '';

  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((windows) => {
      const open = windows.filter((c) => c.url.startsWith(self.location.origin));
      // ⚠⚠ A row with NOWHERE to go takes the tap nowhere. There used to be a
      // `FILEX_FALLBACK_URL = '/admin/explore'` here, so a notification about
      // the instance — a replica failure, an available update, anything whose
      // target is `none` — navigated a tab to an ADMIN address on a tap. For a
      // non-admin that is a guard bounce out of whatever they were doing; for
      // an admin it is the folder they were standing in, thrown away for a row
      // that was not about a folder. Rule 1, docs/NOTIFICATIONS.md: a
      // notification is clickable exactly when it has somewhere to go. The
      // bell draws that row as plain text; this is the same row, and the same
      // answer. Focusing a window the person already has open is the most a
      // tap on it may do.
      if (!target) return open.length ? open[0].focus() : undefined;

      const absolute = new URL(target, self.location.origin).href;
      // Prefer a tab already on this origin: focus it and send it where the
      // notification points. ⚠ `navigate()` is not available on every client
      // (and rejects cross-origin), so a failure falls through to opening a
      // window rather than leaving the tap doing nothing.
      for (const client of open) {
        const go = client.focus();
        return Promise.resolve(go)
          .then(() => ('navigate' in client ? client.navigate(absolute) : null))
          .catch(() => self.clients.openWindow(absolute));
      }
      return self.clients.openWindow(absolute);
    }),
  );
});

self.addEventListener('push', (event) => {
  let payload = {};
  try {
    payload = event.data ? event.data.json() : {};
  } catch (_) {
    payload = { body: event.data ? event.data.text() : '' };
  }

  // The sender may name the instance (an operator renames it on the Branding
  // page); "filex" is only the fallback, exactly as in the page's own channel.
  const title = payload.title || 'filex';
  const options = {
    body: payload.body || '',
    icon: payload.icon || FILEX_ICON,
    badge: payload.badge || FILEX_BADGE,
    tag: payload.tag || undefined,
    renotify: payload.tag ? true : undefined,
    // ⚠ No fallback address. A push with no `url` is a push about nothing in
    // particular, and the click handler above treats "no url" as "nowhere to
    // go" — the same answer the bell gives the same row.
    data: { url: payload.url || '' },
  };
  event.waitUntil(self.registration.showNotification(title, options));
});
